tasks.starter:
const outbox = [
  { id: 1, ev: 'order.created' },
  { id: 2, ev: 'payment.charged' },
  { id: 3, ev: 'receipt.sent' },
];
const published = [];
let attempts = 0;
function brokerSend(ev) {
  attempts++;
  if (ev === 'payment.charged' && attempts <= 2) throw new Error('broker down');
  published.push(ev);
}
// BUG: one pass, no error handling, clears everything regardless
function relay() {
  for (const row of outbox) brokerSend(row.ev);
  outbox.length = 0;
}

tasks.verify:
relay();
if (JSON.stringify(published) !== '["order.created","payment.charged","receipt.sent"]') throw new Error('published=' + JSON.stringify(published));
if (outbox.length !== 0) throw new Error('outbox not drained, left=' + outbox.length);
console.log('__PASS__');
